namespace {
template<class T>const T* find(const std::vector<T>& rows,const StableId& id){for(const auto& row:rows)if(row.id==id)return &row;return nullptr;}
NavalBattleRecord* battle(NavalBattleState& state,const StableId& id){for(auto& row:state.battles)if(row.frame.id==id)return &row;return nullptr;}
std::vector<StableId> sorted(std::vector<StableId> rows){std::sort(rows.begin(),rows.end());return rows;}
bool precedes(const CommonStore& common,const StableId& a,const StableId& b){const auto& rows=common.state().facts.order();auto x=std::find(rows.begin(),rows.end(),a),y=std::find(rows.begin(),rows.end(),b);return x!=rows.end()&&y!=rows.end()&&x<y;}
}
