  if(kind=="naval_form"||kind=="naval_disband"){const NavalFleetRecord* fleet=nullptr;for(const auto& f:naval.fleets)if(f.source_id==id||f.release_source_id==id)fleet=&f;if(fleet)for(const auto& b:replay.battles)if(b.frame.phase!="closed")for(const auto& link:b.frame.bindings)if(link.fleet_id==fleet->id)return common_failure("NavalFleetHistoryOverlap",id);return common_success();}
