  if(kind=="naval_voyage"||kind=="naval_navigation_step"){StableId fleet;if(kind=="naval_voyage"){const auto* f=find(naval.navigation.voyages,id);if(!f)return common_failure("NavalVoyageSourceRequired",id);fleet=f->fleet_id;}else{const auto* f=find(naval.navigation.steps,id);if(!f)return common_failure("NavalNavigationSourceRequired",id);fleet=f->fleet_id;}for(const auto& b:replay.battles)if(b.frame.phase!="closed")for(const auto& link:b.frame.bindings)if(link.fleet_id==fleet)return common_failure("NavalNavigationBattleOccupationOverlap",id);return common_success();}
