Status validate_naval_battle_history(const CommonStore& common,const MilitaryState& military,const MilitaryCatalog& commands,const MilitaryAccess& access,const TravelState& travel,const NavalState& naval,const NavalCatalog& ships,const NavalHistoryAccess& history){return history_impl(common,military,commands,access,travel,naval,ships,history,GunneryHistoryStage::all_sources);}
Status validate_naval_battle_structure_for_gunnery(const CommonStore& common,const MilitaryState& military,const MilitaryCatalog& commands,const MilitaryAccess& access,const TravelState& travel,const NavalState& naval,const NavalCatalog& ships,const NavalHistoryAccess& history){if(!ships.combat_policy||!ships.combat_policy->combat.gunnery)return common_failure("NavalGunneryProfileRequired");return history_impl(common,military,commands,access,travel,naval,ships,history,GunneryHistoryStage::structure_only);}

Status validate_naval_battle_history_with_exact_repairs(const CommonStore& c,const MilitaryState& m,const MilitaryCatalog& mc,const MilitaryAccess& a,const TravelState& t,const NavalState& n,const NavalCatalog& d,const NavalHistoryAccess& h,const ExactNavalAssetHistoryContext& exact){return history_impl(c,m,mc,a,t,n,d,h,GunneryHistoryStage::all_sources,&exact);}
Status visit_naval_battles_before_exact_repair_source(const CommonStore& c,const MilitaryState& m,const MilitaryCatalog& mc,const MilitaryAccess& a,const TravelState& t,const NavalState& n,const NavalCatalog& d,const NavalHistoryAccess& h,const ExactNavalAssetHistoryContext& exact,const SourceRef& boundary,Integer schema,const NavalBattlePrefixObserver& observer){if(schema!=2||!observer)return common_failure("ExactNavalBattleBoundaryRequired",boundary.id);return history_impl(c,m,mc,a,t,n,d,h,GunneryHistoryStage::all_sources,&exact,&boundary,&observer);}

Status visit_naval_battle_source_history_with_exact_repairs(const CommonStore& c,const MilitaryState& m,const MilitaryCatalog& mc,const MilitaryAccess& a,const TravelState& t,const NavalState& n,const NavalCatalog& d,const NavalHistoryAccess& h,const ExactNavalAssetHistoryContext& exact,const NavalBattlePrefixObserver& observer){if(!observer)return common_failure("ExactNavalBattleSourceObserverRequired");return history_impl(c,m,mc,a,t,n,d,h,GunneryHistoryStage::all_sources,&exact,nullptr,&observer,true);}

Status visit_naval_history_at_actual_prefix(const CommonStore& c,const MilitaryState& m,const MilitaryCatalog& mc,const MilitaryAccess& a,const TravelState& t,const NavalState& n,const NavalCatalog& d,const NavalHistoryAccess& h,const ExactNavalAssetHistoryContext& exact,const CommonActualFactPrefix& prefix,const WorldMoment& at,const NavalOriginalPrefixObserver& observer){
 if(!h.original_sources||exact.original_sources!=h.original_sources)return common_failure("NavalActualPrefixContextRequired");
 auto actual_now=h.original_sources->authority.office.clock.read_current_moment();if(!actual_now.ok)return {false,{},actual_now.error};const auto& now=actual_now.value;const MilitaryActualSourceWindow window{prefix,at};NavalWindowedFormationSourceRead formations{*h.original_sources,window,now};NavalWindowedReturnSourceRead returns{*h.original_sources,window,now};const auto& original=*h.original_sources;NavalOriginalSourceContext sources{original.common,original.military,original.exact,original.actions,original.elapsed,original.authority,formations,returns,original.periods,&window};auto history=h;history.original_sources=&sources;auto context=exact;context.original_sources=&sources;
 return history_impl(c,m,mc,a,t,n,d,history,GunneryHistoryStage::all_sources,&context,nullptr,nullptr,false,&prefix,&at,&observer);
}
Outcome<bool> naval_actor_held_at_actual_prefix(const CommonStore& c,const MilitaryState& m,const MilitaryCatalog& mc,const MilitaryAccess& a,const TravelState& t,const NavalState& n,const NavalCatalog& d,const NavalHistoryAccess& h,const ExactNavalAssetHistoryContext& exact,const StableId& actor,const CommonActualFactPrefix& prefix,const WorldMoment& at){
 const auto* original=h.original_sources;if(!original||exact.original_sources!=original)return {false,{},common_failure("NavalActualPrefixContextRequired").error};auto now=original->authority.office.clock.read_current_moment();if(!now.ok)return {false,{},now.error};const MilitaryActualSourceWindow window{prefix,at};NavalWindowedFormationSourceRead formations{*original,window,now.value};NavalWindowedReturnSourceRead returns{*original,window,now.value};bool held=false;
 NavalOriginalPrefixObserver inspect=[&](const NavalAssetState& assets,const NavalBattleState& battles)->Status{
  // Deduplication changes no membership. Do not consult active fleets, alive
  // actors, the tactical/contact roster or current commander/member fields.
  auto less=[](const StableId* a,const StableId* b){return *a<*b;};std::set<const StableId*,decltype(less),CheckpointAllocator<const StableId*>> occupied(less);for(const auto& battle:battles.battles)if(battle.frame.phase!="closed")for(const auto& binding:battle.frame.bindings)occupied.insert(&binding.fleet_id);
  for(const auto* identity:occupied){const auto& id=*identity;const auto* fleet=find(assets.fleets,id);const auto* army=fleet?find(m.armies,fleet->army_id):nullptr;if(!fleet||!army)return common_failure("NavalHeldArmySourceRequired",id);
   auto commander=read_military_army_command_source_at_actual_prefix(c,m,army->id,prefix,at,now.value,&formations,original->authority.office.budget);if(!commander.ok)return {false,{},commander.error};
   auto members=read_military_army_member_refs_at_actual_prefix(c,m,original->exact,army->id,prefix,at,now.value,original->authority.office.budget,&formations,&returns);if(!members.ok)return {false,{},members.error};
   held=held||commander.value.commander_actor_id==actor;for(const auto* member:members.value){if(!member)return common_failure("NavalHeldMemberSourceRequired",army->id);held=held||*member==actor;}
  }
  return common_success();
 };
 auto checked=visit_naval_history_at_actual_prefix(c,m,mc,a,t,n,d,h,exact,prefix,at,inspect);if(!checked.ok)return {false,{},checked.error};return {true,held,{}};
}

